import{_ as t,o as a,c as d,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0037 — Modèle d'embedding proposé par défaut : BGE-M3, exécuté localement","description":"Extrait de docs/adr/0037-modele-embedding-par-defaut-bge-m3.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0037 — Modèle d'embedding proposé par défaut : BGE-M3, exécuté localement","description":"Extrait de docs/adr/0037-modele-embedding-par-defaut-bge-m3.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0037-modele-embedding-par-defaut-bge-m3.md","filePath":"developpeurs/adr/0037-modele-embedding-par-defaut-bge-m3.md"}`),i={name:"developpeurs/adr/0037-modele-embedding-par-defaut-bge-m3.md"};function o(r,e,s,l,u,c){return a(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0037--modèle-dembedding-proposé-par-défaut--bge-m3-exécuté-localement" tabindex="-1">ADR-0037 — Modèle d&#39;embedding proposé par défaut : BGE-M3, exécuté localement <a class="header-anchor" href="#adr-0037--modèle-dembedding-proposé-par-défaut--bge-m3-exécuté-localement" aria-label="Permalink to &quot;ADR-0037 — Modèle d&#39;embedding proposé par défaut : BGE-M3, exécuté localement {#adr-0037--modèle-dembedding-proposé-par-défaut--bge-m3-exécuté-localement}&quot;">​</a></h1><p><strong>Date :</strong> 19 septembre 2026 <strong>Statut :</strong> Accepté avec garde-fou <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §14.2, §14.3, §14.8, §17 point ouvert #4 ; revue documentaire du 18/09/2026 (contradiction relevée dans <code>docs/adr/actions-ouvertes.md</code>) ; tranche la décision de fond différée par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0004-modele-embedding-par-defaut">ADR-0004</a>, sans toucher à ses garde-fous</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0004 avait différé le choix du modèle d&#39;embedding à l&#39;Epic E8, « pour s&#39;appuyer sur des données réelles », tout en exigeant la décision <strong>avant</strong> E8. E8 est livré avec ses garde-fous : la dimension <code>pgvector</code> se verrouille au premier modèle réellement déployé, et changer de modèle exige une réindexation planifiée. Mais le choix, lui, n&#39;a jamais été fait.</p><ul><li>Le catalogue décrit trois candidats sans en élire un : <code>nomic-embed-text</code> (768 dimensions), <code>bge-m3</code> (1024) et <code>text-embedding-3-small</code> (1536).</li><li>Le réglage <code>AI_DEFAULT_EMBEDDING_MODEL</code> était vide, et <strong>aucun code ne le lisait</strong>.</li></ul><p>Une collectivité qui active la recherche assistée devait donc choisir seule un modèle, sans critère. C&#39;est exactement le choix « non informé » que l&#39;ADR-0004 voulait éviter, reporté sur chaque installation.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong><code>ollama/bge-m3</code> est le modèle d&#39;embedding proposé par défaut.</strong> Il est déjà au catalogue.</p><table tabindex="0"><thead><tr><th>Critère de l&#39;ADR-0004</th><th>BGE-M3 (retenu)</th><th>nomic-embed-text</th><th>text-embedding-3-small</th></tr></thead><tbody><tr><td>Couverture du français</td><td>multilingue par conception (plus de cent langues)</td><td>entraîné surtout sur de l&#39;anglais</td><td>multilingue</td></tr><tr><td>Auto-hébergement</td><td>oui : poids ouverts sous licence MIT, servis par Ollama</td><td>oui</td><td><strong>non</strong> : service distant hors UE</td></tr><tr><td>Dimension</td><td>1024</td><td>768</td><td>1536</td></tr><tr><td>Longueur d&#39;entrée</td><td>8 192 jetons</td><td>8 192</td><td>8 191</td></tr><tr><td>Coût</td><td>calcul local, sans tarif</td><td>calcul local</td><td>à l&#39;usage</td></tr></tbody></table><p><strong>Pourquoi lui.</strong></p><ul><li>Le mode de souveraineté par défaut (<code>restricted</code>, CDC §14.8) écarte d&#39;emblée le candidat distant : une installation neuve ne l&#39;appellerait jamais.</li><li>Entre les deux candidats locaux, <strong>le français tranche</strong> : les contenus d&#39;une collectivité sont en français, et un modèle entraîné surtout sur de l&#39;anglais les représente moins bien.</li><li>La longueur d&#39;entrée permet d&#39;indexer des fragments de la taille d&#39;une page sans les couper artificiellement.</li><li>Une dimension plus grande coûte un peu plus de stockage par vecteur, ce qui est négligeable au volume d&#39;une collectivité.</li></ul><p><strong>Ce que « par défaut » veut dire.</strong> Le Provider Manager pose un principe qui ne change pas : <em>sans politique, rien ne part ; une installation neuve ne devine pas un modèle.</em> Le défaut est donc une <strong>recommandation</strong>, jamais un appel d&#39;office :</p><ol><li><code>AI_DEFAULT_EMBEDDING_MODEL</code> vaut <code>ollama/bge-m3</code>. Il est <strong>vérifié au démarrage</strong> : une clé inconnue du catalogue, ou d&#39;une autre capacité, refuse le démarrage. Vide, il signifie « aucune recommandation ».</li><li>Il est proposé à l&#39;administrateur quand celui-ci pose la politique de la tâche d&#39;indexation vectorielle, et prérempli dans l&#39;écran. <strong>Rien n&#39;est vectorisé tant qu&#39;un administrateur n&#39;a pas posé cette politique.</strong></li><li>Les garde-fous de l&#39;ADR-0004 restent entiers : la dimension se verrouille au premier modèle réellement déployé, et en changer exige une réindexation.</li></ol><p><strong>Le garde-fou de cette ADR : le choix repose sur les caractéristiques publiées des modèles, pas sur un banc d&#39;essai mené par ce projet sur des contenus de collectivité.</strong> Le modèle reste donc <code>candidate</code> au catalogue, et non <code>validated</code>. Ce statut attend une évaluation réelle.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Continuer à ne rien choisir</strong></td><td>Reporte sur chaque collectivité un choix technique qu&#39;elle n&#39;a pas les moyens d&#39;instruire, et laisse la contradiction de l&#39;ADR-0004 ouverte.</td></tr><tr><td><strong><code>nomic-embed-text</code></strong></td><td>Local et léger, mais entraîné surtout sur de l&#39;anglais : moins adapté à des contenus en français.</td></tr><tr><td><strong><code>text-embedding-3-small</code></strong> ou un autre service distant</td><td>Contredit le mode de souveraineté par défaut, et ferait sortir le texte des contenus vers un tiers à chaque indexation.</td></tr><tr><td><strong>Appeler le modèle par défaut sans politique</strong></td><td>Contredirait le principe du Provider Manager : une installation neuve contacterait un modèle sans décision d&#39;un administrateur.</td></tr><tr><td><strong>Attendre un banc d&#39;essai complet avant de choisir</strong></td><td>C&#39;était la position de l&#39;ADR-0004, et elle n&#39;a pas été tenue. Mieux vaut un défaut raisonné et révisable, puisque changer de modèle est prévu (réindexation), qu&#39;une absence de défaut.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une collectivité qui active la recherche assistée part d&#39;un choix raisonné, local et adapté au français.</li><li>La contradiction de l&#39;ADR-0004 est levée sans affaiblir ses garde-fous.</li><li>Le réglage <code>AI_DEFAULT_EMBEDDING_MODEL</code> a enfin un effet, et une valeur invalide est refusée au démarrage.</li></ul><p><strong>Négatives</strong></p><ul><li>L&#39;exploitant qui veut la recherche vectorielle doit télécharger le modèle dans Ollama (<code>ollama pull bge-m3</code>, un peu plus d&#39;un gigaoctet) et disposer de la mémoire pour le servir.</li><li>Une installation qui a déjà indexé avec un autre modèle garde le sien : ce défaut ne s&#39;applique qu&#39;à la première politique posée.</li><li>Si une évaluation réelle désavoue ce choix, en changer coûtera une réindexation. C&#39;est prévu par l&#39;ADR-0004, mais pas gratuit.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[ ] Évaluer BGE-M3 sur un corpus réel de collectivité (recherche de pages, questions d&#39;usagers), contre au moins un autre candidat local, avant de le déclarer <code>validated</code> au catalogue.</li></ul>',23)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
